/**
 * Bi-wheel request: natal chart inside, secondary progressed chart outside.
 *
 * Mirrors `ExperimentalTransitChartRequest`; only the outer wheel differs. The
 * progressed instant follows the classic rule used by
 * `/api/v1/western/progressions/secondary`: one ephemeris day after birth per
 * tropical year of life elapsed at `progression_date`.
 */
export interface ExperimentalSecondaryProgressionsChartRequest {
  natal: ExperimentalNatalChartRequest;
  /**
   * Real-world date the chart is progressed to: `YYYY-MM-DD` (local midnight at the progression location) or an ISO datetime. Defaults to now (UTC).
   */
  progression_date?: string | null;
  progression_lat?: number | null;
  progression_lng?: number | null;
  /**
   * Location used for the progressed houses/angles and for interpreting a local `progression_date`. Defaults to the natal location when omitted together with the coordinates.
   */
  progression_city?: string | null;
  /**
   * Timezone of `progression_date`. `AUTO` resolves it from the progression location.
   */
  tz_str?: string | null;
  dst_policy?: ("reject" | "earlier" | "later" | "shift_forward") | null;
  show_natal_aspects?: boolean;
  show_inter_aspects?: boolean;
  show_progressed_aspects?: boolean;
  /**
   * Maximum orb (degrees) for progressed aspect lines. Default 1.0, matching /api/v1/western/progressions/secondary.
   */
  orb_deg?: number;
  /**
   * `major` draws conjunction/opposition/trine/square/sextile; `major_plus` also draws the quincunx.
   */
  aspect_set?: "major" | "major_plus";
  /**
   * Per-aspect orb overrides (degrees) for progressed aspect lines, e.g. {"conjunction": 1.5}.
   */
  orb_settings?: AspectOrbSettings | null;
  /**
   * `progressed_outside` (default): French layout with natal planets inside the sign ring and progressed planets on the outer ring. `progressed_inside`: the transits-chart layout, with the progressed planets drawn on the inner lane. Explicit `chart_config.french_style` / `french_transit_natal_planets_inside` values always win.
   */
  layout?: "progressed_outside" | "progressed_inside";
  /**
   * Draw the progressed ASC/MC glyphs on the outer wheel (requires a known birth time).
   */
  show_progressed_angles?: boolean;
  /**
   * Draw the progressed house cusps as a secondary house wheel (requires a known birth time). In the default `progressed_outside` layout the cusp ring sits beyond the progressed planets; with `progressed_inside` it sits inside the sign ring.
   */
  show_progressed_houses?: boolean;
  natal_planet_color?: string | null;
  progressed_planet_color?: string | null;
  chart_config?: ExperimentalChartConfigSettings | null;
  custom_planet_color?: string | null;
  custom_sign_color?: string | null;
  custom_house_color?: string | null;
  custom_sign_bg_color?: string | null;
  custom_house_bg_color?: string | null;
  show_sign_background?: boolean | null;
  show_house_background?: boolean | null;
  custom_sign_colors?: Array<string> | null;
  custom_house_colors?: Array<string> | null;
  sign_background_opacity?: number | null;
  house_background_opacity?: number | null;
  show_retrograde_markers?: boolean | null;
  retrograde_marker_style?: ("R" | "rx") | null;
}

